func init() {
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt: deferred init SwtTestUtil static{}:", r)
			}
		}()
		SwtTestUtilTestFontName = "Helvetica"
		if SwtTestUtilIsCocoa {
			SwtTestUtilTestFontNameFixedWidth = "Monaco"
		} else {
			if SwtTestUtilIsGTK {
				SwtTestUtilTestFontNameFixedWidth = "Monospace"
			} else {
				if SwtTestUtilIsWindows {
					SwtTestUtilTestFontNameFixedWidth = "Consolas"
				} else {
					SwtTestUtilTestFontNameFixedWidth = ""
					junit.Fail("A fixed width font is needed for this platform")
				}
			}
		}
	}()
}
